/**
 * Phantom generators.
 *
 * A phantom is generated by ray-casting the target shape along the directions
 * the spoofer can actually reach, rather than by sampling the shape's surface.
 * Two things fall out for free:
 *
 *   - the phantom has exactly one point per lattice cell, so it is realizable by
 *     construction (fill <= 1) instead of needing a later dedupe;
 *   - its point density falls off with range and its silhouette is the one the
 *     victim's own scan pattern would produce, which is what makes an injected
 *     object look like a real detection rather than a blob.
 */
import { sphericalToCart, unpackCellKey } from "./polar.js";

export const PHANTOM_SHAPES = ["box", "wall"];

/**
 * Distance from the sensor origin to an oriented box along unit direction `d`,
 * or Infinity if the ray misses. Slab test in the box's own frame.
 */
export function rayBox(d, { center, size, yaw = 0 }) {
  const c = Math.cos(-yaw);
  const s = Math.sin(-yaw);

  // origin -> box centre, rotated into box axes
  const ox = -center[0];
  const oy = -center[1];
  const oz = -center[2];
  const lox = ox * c - oy * s;
  const loy = ox * s + oy * c;
  const loz = oz;

  const ldx = d[0] * c - d[1] * s;
  const ldy = d[0] * s + d[1] * c;
  const ldz = d[2];

  const h = [size[0] / 2, size[1] / 2, size[2] / 2];
  const lo = [lox, loy, loz];
  const ld = [ldx, ldy, ldz];

  let tMin = -Infinity;
  let tMax = Infinity;
  for (let a = 0; a < 3; a++) {
    if (Math.abs(ld[a]) < 1e-12) {
      if (Math.abs(lo[a]) > h[a]) return Infinity;
      continue;
    }
    const inv = 1 / ld[a];
    let t1 = (-h[a] - lo[a]) * inv;
    let t2 = (h[a] - lo[a]) * inv;
    if (t1 > t2) {
      const tmp = t1;
      t1 = t2;
      t2 = tmp;
    }
    if (t1 > tMin) tMin = t1;
    if (t2 < tMax) tMax = t2;
    if (tMin > tMax) return Infinity;
  }
  if (tMax < 0) return Infinity;
  return tMin >= 0 ? tMin : tMax;
}

/** Direction unit vector of a lattice cell's centre. */
function cellDirection(cellKeyValue, sensor) {
  const { azIdx, beamIdx } = unpackCellKey(cellKeyValue, sensor.nBeams);
  const az = (azIdx + 0.5) * sensor.azRes;
  const el = sensor.inclinations[beamIdx];
  const ce = Math.cos(el);
  return [ce * Math.cos(az), ce * Math.sin(az), Math.sin(el)];
}

function pack(xs, ys, zs, cells) {
  return {
    x: Float64Array.from(xs),
    y: Float64Array.from(ys),
    z: Float64Array.from(zs),
    cell: Int32Array.from(cells),
  };
}

/** A phantom vehicle: an oriented box, ray-cast from the victim's origin. */
export function boxPhantom({ box, sensor, reach }) {
  const xs = [];
  const ys = [];
  const zs = [];
  const cells = [];
  for (let i = 0; i < reach.cells.length; i++) {
    const key = reach.cells[i];
    const d = cellDirection(key, sensor);
    const t = rayBox(d, box);
    if (!Number.isFinite(t)) continue;
    xs.push(d[0] * t);
    ys.push(d[1] * t);
    zs.push(d[2] * t);
    cells.push(key);
  }
  return pack(xs, ys, zs, cells);
}

/** A phantom wall: every reachable cell filled at one constant range. */
export function wallPhantom({ range, sensor, reach }) {
  const xs = [];
  const ys = [];
  const zs = [];
  const cells = [];
  for (let i = 0; i < reach.cells.length; i++) {
    const key = reach.cells[i];
    const { azIdx, beamIdx } = unpackCellKey(key, sensor.nBeams);
    const [x, y, z] = sphericalToCart(
      range,
      (azIdx + 0.5) * sensor.azRes,
      sensor.inclinations[beamIdx]
    );
    xs.push(x);
    ys.push(y);
    zs.push(z);
    cells.push(key);
  }
  return pack(xs, ys, zs, cells);
}

/** Dispatch used by the UI. */
export function makePhantom({ shape, sensor, reach, box, range }) {
  if (shape === "box") return boxPhantom({ box, sensor, reach });
  if (shape === "wall") return wallPhantom({ range, sensor, reach });
  throw new Error('unknown phantom shape "' + shape + '"');
}
